import 'dart:io';

import 'package:sg_platform/sg_platform.dart';

/// Shows the server's time (`phone time + offset`). Attendance is stamped by
/// the server, so the app uses the same clock to decide "late", "today" and
/// the cooldown message.
class ApiClock implements ClockService {
  new([this.offset = Duration.zero]);

  Duration offset;

  @override
  DateTime now() => DateTime.now().add(offset);
}

/// Saves a downloaded export under the temp folder so the share sheet can send
/// it. Names are generated by the server; anything unexpected is cleaned.
Future<String> saveExportToTemp(String fileName, List<int> bytes) async {
  final safe = fileName.replaceAll(RegExp('[^A-Za-z0-9._-]'), '_');
  final dir = await Directory(
    '${Directory.systemTemp.path}${Platform.pathSeparator}syncgate_exports',
  ).create(recursive: true);
  final file = File('${dir.path}${Platform.pathSeparator}$safe');
  await file.writeAsBytes(bytes, flush: true);
  return file.path;
}
